import React, { useRef, useEffect, useState } from "react";
import WeddingVenueCanvas from "./WeddingVenueCanvas";
import { HERO_LABELS, BRAND } from "./Content";
import { ArrowDownRight, Sparkles } from "lucide-react";

export default function Hero({ onOpenQuote }) {
  const hostRef = useRef(null);
  const pointerRef = useRef({ x: 0, y: 0 });
  const [activeLabel, setActiveLabel] = useState(null);
  const [mouse, setMouse] = useState({ x: 50, y: 50 });

  useEffect(() => {
    const onMove = (e) => {
      if (!hostRef.current) return;
      const r = hostRef.current.getBoundingClientRect();
      const nx = (e.clientX - r.left) / r.width;
      const ny = (e.clientY - r.top) / r.height;
      pointerRef.current.x = nx * 2 - 1;
      pointerRef.current.y = ny * 2 - 1;
      setMouse({ x: nx * 100, y: ny * 100 });

      let best = null;
      let bestDist = Infinity;
      HERO_LABELS.forEach((l) => {
        const dx = l.x - nx * 100;
        const dy = l.y - ny * 100;
        const d = dx * dx + dy * dy;
        if (d < bestDist) {
          bestDist = d;
          best = l;
        }
      });
      if (bestDist < 22 * 22) setActiveLabel(best);
      else setActiveLabel(null);
    };
    const onLeave = () => setActiveLabel(null);
    const el = hostRef.current;
    if (el) {
      el.addEventListener("mousemove", onMove);
      el.addEventListener("mouseleave", onLeave);
    }
    return () => {
      if (el) {
        el.removeEventListener("mousemove", onMove);
        el.removeEventListener("mouseleave", onLeave);
      }
    };
  }, []);

  return (
    <section
      ref={hostRef}
      className="relative w-full overflow-hidden grain"
      style={{ height: "100vh", minHeight: 720, background: "#0d0405" }}
      data-testid="hero-section"
    >
      <div className="absolute inset-0">
        <WeddingVenueCanvas pointerRef={pointerRef} />
      </div>

      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background: `radial-gradient(600px circle at ${mouse.x}% ${mouse.y}%, rgba(212,175,55,0.12), transparent 60%)`,
        }}
      />

      {activeLabel && (
        <div
          className="hero-label"
          style={{
            left: `${activeLabel.x}%`,
            top: `${activeLabel.y}%`,
            transition: "opacity 280ms ease, transform 280ms ease",
          }}
          data-testid={`hero-label-${activeLabel.id}`}
        >
          {activeLabel.title}
        </div>
      )}

      <div className="absolute inset-0 z-10 flex flex-col justify-end md:justify-center px-6 md:px-12 lg:px-24 pb-24 md:pb-0">
        <div className="max-w-5xl">
          <div className="overline mb-6 flex items-center gap-3" data-testid="hero-overline">
            <span className="inline-block w-10 h-px" style={{ background: "#d4af37" }} />
            Ludhiana &middot; Pan India Delivery
          </div>
          <h1
            className="serif gold-shimmer leading-[0.92] tracking-tight"
            style={{ fontSize: "clamp(56px, 10vw, 168px)", fontWeight: 300 }}
            data-testid="hero-title"
          >
            D SAJAWAT
          </h1>
          <p
            className="serif mt-4 md:mt-6"
            style={{
              fontSize: "clamp(20px, 2.4vw, 34px)",
              color: "#f7e7ce",
              fontStyle: "italic",
              maxWidth: 720,
              lineHeight: 1.25,
            }}
            data-testid="hero-tagline"
          >
            {BRAND.tagline}
          </p>
          <p className="mt-5 text-base md:text-lg" style={{ color: "rgba(255,255,240,0.6)", maxWidth: 560 }}>
            A fabric atelier crafting magical wedding venues for India's most discerning decorators.
          </p>

          <div className="mt-9 flex flex-wrap gap-4">
            <a href="#collections" className="btn-gold" data-testid="hero-explore-btn">
              <Sparkles size={16} strokeWidth={1.6} />
              Explore Our Collection
            </a>
            <button onClick={onOpenQuote} className="btn-ghost" data-testid="hero-quote-btn" type="button">
              Get a Quote
              <ArrowDownRight size={16} strokeWidth={1.6} />
            </button>
          </div>
        </div>
      </div>

      <div className="absolute bottom-6 right-6 md:right-12 z-10 text-right">
        <div className="overline mb-1" style={{ color: "rgba(247,231,206,0.7)" }}>
          Move cursor to explore
        </div>
        <div className="serif italic" style={{ color: "#f7e7ce", fontSize: 14 }}>
          a 3D venue, alive
        </div>
      </div>

      <div
        className="pointer-events-none absolute inset-x-0 bottom-0 h-40"
        style={{ background: "linear-gradient(to bottom, rgba(13,4,5,0) 0%, #0d0405 100%)" }}
      />
    </section>
  );
}
